{
 "S001": {
  "text": "血结石有点五掉了，多许多五老掉了。",
  "language": "Chinese"
 },
 "S002": {
  "text": "你平时修一毛毛，我冇修。",
  "language": "Chinese"
 },
 "S003": {
  "text": "这件事，你该当会当，我该当。这件事，你该当有无，有我该当。",
  "language": "Chinese"
 },
 "S004": {
  "text": "你是胖还是盲的？",
  "language": "Chinese"
 },
 "S005": {
  "text": "你到底答人东西啊？",
  "language": "Chinese"
 },
 "S006": {
  "text": "喊小强一起去天云村，天云刘三姐干破天云，更宽过的，更宽过的干破天云。",
  "language": "Chinese"
 },
 "S007": {
  "text": "给他建个碑，过吧，又是挖煤钱；给他建个碑，过过吧，又是挖煤钱。",
  "language": "Chinese"
 },
 "S008": {
  "text": "佢啲教室装了空调喎。",
  "language": "Chinese"
 },
 "S009": {
  "text": "顶无去向配合，顶无去向找手。",
  "language": "Chinese"
 },
 "S010": {
  "text": "蒋明被法庭枪决的一个包，人肉草垫子被没收。",
  "language": "Chinese"
 },
 "S011": {
  "text": "快到雨天，你莫出去的。",
  "language": "Chinese"
 },
 "S012": {
  "text": "看到手机，过去拉谁个哩？独瓜个个。",
  "language": "Chinese"
 },
 "S013": {
  "text": "你是到去干呢？我哪到去？我是到花老院子呢。",
  "language": "Chinese"
 },
 "S014": {
  "text": "我食过兔肉啦，你食过冇？冇，我冇你食过。",
  "language": "Chinese"
 },
 "S015": {
  "text": "我属那个，行起步来拍篮球哦。",
  "language": "Chinese"
 },
 "S016": {
  "text": "我上的铁块上车里，头，我扎上一面。",
  "language": "Chinese"
 },
 "S017": {
  "text": "极快活，又唱起歌来了。",
  "language": "Chinese"
 },
 "S018": {
  "text": "才下了一百，还要下个。",
  "language": "Chinese"
 },
 "S019": {
  "text": "你被我借了，给被你娃借了。",
  "language": "Chinese"
 },
 "S020": {
  "text": "老王跟老张一样高。",
  "language": "Chinese"
 },
 "S021": {
  "text": "我找你两人在座的空间。",
  "language": "Chinese"
 },
 "S022": {
  "text": "我讲唔够多，这个家伙满手都讲唔够多。",
  "language": "Chinese"
 },
 "S023": {
  "text": "上次只买的一本书，今天又多买几本的。",
  "language": "Chinese"
 },
 "S024": {
  "text": "俺哪个年个水是俺交政府个秋耕下的耶。",
  "language": "Chinese"
 }
}
